const CACHE="nexus-tutor-0.1.0",ASSETS=["./","./index.html","./styles.min.css","./config.min.js","./app.min.js","./manifest.webmanifest","./icon.svg"];self.addEventListener("install",e=>{e.waitUntil(caches.open(CACHE).then(e=>e.addAll(ASSETS)).then(()=>self.skipWaiting()))}),self.addEventListener("activate",e=>{e.waitUntil(caches.keys().then(e=>Promise.all(e.filter(e=>e!==CACHE).map(e=>caches.delete(e)))).then(()=>self.clients.claim()))}),self.addEventListener("fetch",e=>{"GET"===e.request.method&&new URL(e.request.url).origin===self.location.origin&&e.respondWith(fetch(e.request).then(t=>{const n=t.clone();return caches.open(CACHE).then(t=>t.put(e.request,n)),t}).catch(()=>caches.match(e.request).then(e=>e||caches.match("./index.html"))))});